solution.code:
// utils.ts — converted and typed
function groupByFirstLetter(words: string[]): Record<string, string[]> {
  const out: Record<string, string[]> = {};
  for (const w of words) {
    const k = w[0];
    (out[k] = out[k] || []).push(w);
  }
  return out;
}

console.log(groupByFirstLetter(['apple', 'avocado', 'banana']));

