solution.code:
function getConfig(): { timeout: number } {
  return { timeout: 5000 };
}

// Fixed the typo; no suppression needed.
const t = getConfig().timeout;

// If a known error MUST be tolerated, prefer self-cleaning:
// @ts-expect-error legacy field, remove after API v2
// const legacy = getConfig().oldField;

console.log(t); // 5000

interface RawConfig {
  timeout?: number;
  retries?: number;
  baseUrl?: string;
}
interface Config {
  timeout: number;
  retries: number;
  baseUrl: string;
}

function normalizeConfig(raw: RawConfig = {}): Config {
  return {
    timeout: raw.timeout ?? 5000,
    retries: raw.retries ?? 3,
    baseUrl: raw.baseUrl ?? 'https://api.example.com'
  };
}

console.log(normalizeConfig({ timeout: 1000 }));
console.log(normalizeConfig());
